import "./App.css";
import { Provider } from "react-redux";
import { Folders } from "./components/Folders";
import { store } from "./store/Stores";
import { Header } from "./components/header";
import { Books } from "./components/ListBooks";
import {
  BrowserRouter as Router,
  Route,
  Routes,
  BrowserRouter,
} from "react-router-dom";
import { MainContext } from "./components/MainContext";
import { Container, createTheme } from "@mui/material";
import { lime } from "@mui/material/colors";
import { grey } from "@mui/material/colors";
import { ThemeProvider } from "@emotion/react";
import { InActiveBook } from "./components/InActiveBooks";

import { BooksFromFolder } from "./components/BooksFromFolder";
import { useSelector } from "react-redux";

function App() {
  const theme = createTheme({
    palette: {
      primary: {
        main: lime[700],
        dark: lime[900],
        light: lime[200],
      },
      secondary: {
        main: grey[400],
        dark: grey[600],
        light: grey[200],
      },
      background: lime[50],
      common: {
        white: grey[50],
      },
    },
    breakpoints: {
      values: {
        xs: 0,
        sm: 600,
        md: 900,
        lg: 1200,
        xl: 1536,
      },
      shape: {
        borderRadiuse: "6px",
      },
    },
    spacing: [0, 4, 8, 16, 32, 64],
  });
  const folders = useSelector((state) => state.libraryfolder.folder);
  console.log(folders);

  return (
    // <Provider store={store}>
    <BrowserRouter basename="/routing-react-kraft/">
      <ThemeProvider theme={theme}>
        <Header />

        <Container
          style={{
            // backgroundColor: theme.palette.background,
            height: "100%",
            p: 2,
          }}
        >
          <Routes>
            <Route path="/" element={<Folders />}></Route>
            {folders.map((item) => (
              <>
                <Route
                  path={`${item.id}`}
                  element={<BooksFromFolder />}
                ></Route>
              </>
            ))}

            <Route path="books" element={<Books />} />
            <Route path="inActive" element={<InActiveBook />} />
          </Routes>
          <MainContext />
        </Container>
      </ThemeProvider>
    </BrowserRouter>
    // </Provider>
  );
}
//backgroundImage: "url('/bg2.jpg')";
export default App;
