import { useSelector } from "react-redux";
import { useState } from "react";
import { useDispatch } from "react-redux";
import { closeDetailsBook, editBooks } from "../reducers/bookSlice";
import { toggleEditBook } from "../reducers/bookSlice";
import { Link } from "react-router-dom";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import ListAltIcon from "@mui/icons-material/ListAlt";
import {
  AppBar,
  Button,
  Stack,
  TextareaAutosize,
  Typography,
} from "@mui/material";
import KeyboardBackspaceOutlinedIcon from "@mui/icons-material/KeyboardBackspaceOutlined";
import CollectionsIcon from "@mui/icons-material/Collections";
import { useTheme } from "@emotion/react";
import PrintTwoToneIcon from "@mui/icons-material/PrintTwoTone";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { LocalizationProvider } from "@mui/x-date-pickers";
import { DatePicker } from "@mui/x-date-pickers";
import { DemoContainer } from "@mui/x-date-pickers/internals/demo";
import Divider from "@mui/material/Divider";
import { Rating } from "@mui/material";
import { addRating } from "../reducers/bookSlice";
import { onChangeRatingHover } from "../reducers/bookSlice";
import { getLabelText } from "../units/rating.ts";
import { labels } from "../units/rating.ts";
import { formatsBook } from "../units/formatsBook.js";
import { genre } from "../units/genre.js";
import { Autocomplete } from "@mui/material";
import { toggleDetails } from "../reducers/folderSlice.js";

function EditBooks() {
  const folders = useSelector((state) => state.libraryfolder.folder);
  const ratingValue = useSelector((state) => state.books.rating);
  const ratingHover = useSelector((state) => state.books.ratingHover);
  const dispatch = useDispatch();
  const selectedBook = useSelector((state) => state.books.selectedBook);
  const [postState, setPostState] = useState(selectedBook.poster.name);
  const arrFolders = folders.map((folder) => folder.name);
  const handleSubmit = (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    const obj = Object.fromEntries(formData);
    if (obj.poster.name === "") {
      obj.poster = selectedBook.poster;
    }
    const data = { ...obj };
    dispatch(editBooks(data));
  };
  console.log(selectedBook.poster);

  const onChangePoster = (e) => {
    let image = URL.createObjectURL(e.target.files[0]);
    localStorage.setItem([e.target.files[0].name], image);
    setPostState(e.target.files[0].name);
  };
  const onCloseEditModal = () => {
    dispatch(toggleEditBook());
    dispatch(closeDetailsBook());
  };
  return (
    <div
      // style={{
      //   backgroundImage: "url('/bg2.jpg')",
      // }}
      className="container"
    >
      <AppBar
        sx={{
          p: 2,
          display: "flex",
          alignItems: "center",
          gap: "16px",
          flexDirection: "row",
        }}
      >
        <Link
          to="books"
          onClick={onCloseEditModal}
          style={{ display: "flex", alignItems: "center" }}
        >
          <KeyboardBackspaceOutlinedIcon
            sx={{ color: useTheme().palette.primary.light }}
          />
        </Link>
        <Typography
          sx={{ color: useTheme().palette.primary.light }}
          variant="h5"
        >
          Редагувати інформацію
        </Typography>
      </AppBar>
      <form className="form" onSubmit={handleSubmit}>
        <TextField
          required
          defaultValue={selectedBook.name}
          sx={{ width: "100%", position: "relative" }}
          id="name"
          name="name"
          label="Назва"
          variant="outlined"
        />
        <Box sx={{ display: "flex", gap: "6px" }}>
          <TextField
            sx={{ width: "70%" }}
            defaultValue={selectedBook.series}
            id="series"
            name="series"
            label="Серія"
            variant="outlined"
          />
          <TextField
            id="part"
            name="part"
            label="Частина"
            defaultValue={selectedBook.part}
            variant="outlined"
          />
        </Box>
        <Box sx={{ display: "flex", gap: "6px", width: "100%" }}>
          <TextField
            defaultValue={selectedBook.lastName}
            sx={{ width: "30%" }}
            id="lastName"
            name="lastName"
            label="Прізвище"
            variant="outlined"
          />
          <TextField
            sx={{ width: "100%" }}
            defaultValue={selectedBook.firstName}
            id="firstName"
            name="firstName"
            label="Ім'я"
            variant="outlined"
          />
        </Box>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            gap: "16px",
          }}
        >
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: "6px",
              width: "30%",
            }}
          >
            <Box sx={{ width: 120 }}>
              <img
                width={"100%"}
                src={
                  selectedBook.poster.name
                    ? localStorage.getItem([postState])
                    : selectedBook.poster
                    ? selectedBook.poster
                    : "/image/book.png"
                }
              />
            </Box>
            <Button variant="outlined">
              <label className="label-file" htmlFor="poster">
                <input
                  //defaultValue={selectedBook.poster.name}
                  id="poster"
                  type="file"
                  name="poster"
                  className="input-file"
                  onChange={onChangePoster}
                />

                <CollectionsIcon />
              </label>
            </Button>
          </Box>
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              gap: "6px",
              flexGrow: 1,
            }}
          >
            <Box
              sx={{
                display: "flex",
                alignItems: "center",
                gap: "8px",
              }}
            >
              <PrintTwoToneIcon color="secondary" fontSize="large" />
              <TextField
                id="publish"
                name="publish"
                fullWidth
                label="Видавництво"
                variant="outlined"
              />
            </Box>
            <LocalizationProvider dateAdapter={AdapterDayjs}>
              <DemoContainer components={["DatePicker"]}>
                <DatePicker
                  label="Дата"
                  id="date"
                  name="date"
                  fullWidth
                  slotProps={{
                    textField: {
                      helperText: "MM/DD/YYYY",
                      sx: { width: "100%" },
                    },

                    mobilePaper: {
                      sx: { backgroundColor: useTheme().palette.background },
                    },
                    desktopPaper: {
                      sx: { backgroundColor: useTheme().palette.background },
                    },
                  }}
                />
              </DemoContainer>
            </LocalizationProvider>
          </Box>
        </Box>
        <Box
          sx={{
            "& > legend": { m: 2 },
            alignSelf: "center",
            m: 3,
            display: "flex",
            alignItems: "center",
            gap: "12px",
          }}
        >
          <Rating
            size="large"
            name="rating"
            precision={0.5}
            value={ratingValue}
            getLabelText={getLabelText}
            onChange={(event, newValue) => {
              dispatch(addRating(newValue));
            }}
            onChangeActive={(event, newHover) => {
              dispatch(onChangeRatingHover(newHover));
            }}
          />
          {ratingValue !== null && (
            <Box sx={{ ml: 2, color: "#ffb30e" }}>
              {labels[ratingHover !== -1 ? ratingHover : ratingValue]}
            </Box>
          )}
        </Box>
        <Autocomplete
          disablePortal
          options={formatsBook}
          defaultValue={selectedBook.format}
          fullWidth
          slotProps={{
            popper: { sx: { backgroundColor: useTheme().palette.background } },
          }}
          renderInput={(params) => (
            <TextField {...params} label="Формат" id="format" name="format" />
          )}
        />

        <Box sx={{ display: "flex", gap: "6px", width: "100%" }}>
          <TextField
            defaultValue={selectedBook.language}
            sx={{ width: "70%" }}
            id="language"
            name="language"
            label="Мова"
            variant="outlined"
          />
          <TextField
            sx={{ flexGrow: 1 }}
            id="page"
            defaultValue={selectedBook.page}
            name="page"
            label="Сторінки"
            variant="outlined"
          />
        </Box>
        <Box
          sx={{
            display: "flex",
            gap: "6px",
            width: "100%",
            alignItems: "center",
          }}
        >
          <TextField
            sx={{ flexGrow: 1 }}
            id="price"
            defaultValue={selectedBook.price}
            name="price"
            label="Ціна"
            variant="outlined"
          />
          <Typography>грн</Typography>
        </Box>
        <Autocomplete
          disablePortal
          options={genre}
          defaultValue={selectedBook.genre}
          fullWidth
          slotProps={{
            popper: { sx: { backgroundColor: useTheme().palette.background } },
          }}
          renderInput={(params) => (
            <TextField {...params} label="Жанр" id="genre" name="genre" />
          )}
        />
        <Box display={"flex"} alignItems={"center"}>
          <ListAltIcon color="secondary" fontSize="large" />
          <span>Резюме</span>
        </Box>
        <TextareaAutosize
          defaultValue={selectedBook.rezume}
          aria-label="minimum height"
          minRows={3}
          style={{ backgroundColor: useTheme().palette.background }}
          name="rezume"
          id="rezume"
          fullWidth
        />
        <Autocomplete
          disablePortal
          options={arrFolders}
          fullWidth
          // getOptionLabel={(option) => option.name}
          defaultValue={selectedBook.folder}
          slotProps={{
            popper: { sx: { backgroundColor: useTheme().palette.background } },
          }}
          renderInput={(params) => (
            <TextField
              {...params}
              label="Полиці"
              id="folder"
              required
              name="folder"
            />
          )}
        />
        <Box
          sx={{
            position: "sticky",
            bottom: "0",
            zIndex: "0",
          }}
        >
          <Stack
            sx={{
              justifyContent: "center",
              alignItems: "flex-end",
              position: "sticky",
            }}
            direction="row"
            spacing={2}
            divider={<Divider orientation="vertical" flexItem />}
          >
            <Button
              variant="contained"
              sx={{ color: useTheme().palette.primary.light }}
              onClick={() => {
                dispatch(toggleEditBook());
              }}
              type="button"
            >
              відмінити
            </Button>
            <Button
              sx={{ color: useTheme().palette.primary.light }}
              variant="contained"
              type="submit"
            >
              зберегти
            </Button>
          </Stack>
        </Box>
      </form>
    </div>
  );
}
export { EditBooks };
