import { createSlice } from "@reduxjs/toolkit";
import { myListFolders } from "../units/initialStateFolders";
const folderSlice = createSlice({
  name: "libraryfolder",
  initialState: {
    folder: [...myListFolders],
    modalAddOpen: false,
    modalEditOpen: false,
    selectedFolderId: null,
    selectedFolder: {},
    detailsOpen: false,
    listBooksOpen: false,
    // searchValue: false,
  },
  reducers: {
    addFolder: (state, action) => {
      state.folder.push({ ...action.payload, detailsOpen: false });
    },
    removeFolder: (state, action) => {
      state.folder = state.folder.filter((item) => item.id !== action.payload);
      state.detailsOpen = !state.detailsOpen;
    },
    toggleAddModal: (state) => {
      state.modalAddOpen = !state.modalAddOpen;
      console.log(state.modalAddOpen);
    },
    toggleDetails: (state) => {
      state.detailsOpen = !state.detailsOpen;
    },

    changeActiveFolder: (state, action) => {
      state.selectedFolderId = action.payload.id;
      state.selectedFolder = action.payload;
    },
    toggleEditFolderModal: (state) => {
      state.modalEditOpen = !state.modalEditOpen;
    },
    editFolder: (state, action) => {
      const folderIndex = state.folder.findIndex(
        (folder) => folder.id === state.selectedFolderId
      );
      state.folder[folderIndex].name = action.payload.newName;
      // state.selectedFolderId = null;
      state.modalEditOpen = !state.modalEditOpen;
    },
    toggleListBooks: (state) => {
      state.listBooksOpen = !state.listBooksOpen;
      console.log(state.listBooksOpen);
    },
    // onChangeSearchValue: (state, action) => {
    //   state.searchValue = action.payload;
    // },
  },
});
export const {
  toggleAddModal,
  addFolder,
  removeFolder,
  toggleDetails,
  openModal,
  changeActiveFolder,
  closeDetails,
  toggleEditFolderModal,
  editFolder,
  toggleListBooks,
} = folderSlice.actions;
export { folderSlice };
