import { useDispatch } from "react-redux";
import { toggleEditFolderModal } from "../../reducers/folderSlice";
import "./modal-details-folder.css";
import { useSelector } from "react-redux";
import FolderDeleteIcon from "@mui/icons-material/FolderDelete";
import { useTheme } from "@emotion/react";
import EditIcon from "@mui/icons-material/Edit";
function ModalDetailsFolder({ onClickRemove }) {
  const dispatch = useDispatch();

  const selectFolderID = useSelector(
    (state) => state.libraryfolder.selectedFolderId
  );

  return (
    <ul style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
      <li
        style={{
          display: "flex",
          gap: "12px",
          alignItems: "center",
        }}
        onClick={() => onClickRemove(selectFolderID)}
      >
        <FolderDeleteIcon sx={{ color: useTheme().palette.primary.dark }} />
        <span>Видалити</span>
      </li>
      <li
        style={{ display: "flex", gap: "12px", alignItems: "center" }}
        onClick={() => dispatch(toggleEditFolderModal())}
      >
        <EditIcon sx={{ color: useTheme().palette.primary.dark }} />
        <span>Змінити назву</span>
      </li>
    </ul>
  );
}
export { ModalDetailsFolder };
