export const labels: { [index: string]: string } = {
  0.5: "Жахливо",
  1: "Не цікаво",
  1.5: "Незадовільно",
  2: "Посередньо",
  2.5: "Задовільно",
  3: "Задовільно+",
  3.5: "Цікаво",
  4: "Чудова",
  4.5: "Відмінно",
  5: "Шедевр",
};

function getLabelText(value: number) {
  return `${value} Star${value !== 1 ? "s" : ""}, ${labels[value]}`;
}
export { getLabelText };
