import { makeStyles } from "@mui/styles";
import { alpha, useTheme } from "@mui/material";

export const folderStyle = makeStyles((theme) => ({
  paper: {
    position: "absolute",
    right: "-10px",
    margin: "0",
    top: "-10px",
    padding: "20px",
    listStyle: "none",
    height: "fit-content",
    transform: "scale(0)",
    zIndex: "9999",
    backgroundColor: useTheme().palette.background,
  },
  modalIsOpen: { transform: "scale(1)" },
  fields: {
    marginTop: "16px",
    width: "100%",
    display: "grid",
    gridTemplateColumns: "repeat(auto-fill, minmax(min(160px, 100%), 1fr))",
    gap: 16,
  },
  cardView: {
    flexDirection: "column",
    height: "25vh",
  },
  link: {
    color: useTheme().palette.secondary.dark,
  },
  active: {
    color: useTheme().palette.primary.dark,
  },
}));
