import React from "react";
import { useState } from "react";
import { useSelector } from "react-redux";
import { addBooks } from "../reducers/bookSlice";
import { useDispatch } from "react-redux";
import { toggleAddBooksModal } from "../reducers/bookSlice";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import ListAltIcon from "@mui/icons-material/ListAlt";
import {
  AppBar,
  Button,
  Stack,
  TextareaAutosize,
  Typography,
} from "@mui/material";
import KeyboardBackspaceOutlinedIcon from "@mui/icons-material/KeyboardBackspaceOutlined";
import CollectionsIcon from "@mui/icons-material/Collections";
import { useTheme } from "@emotion/react";
import PrintTwoToneIcon from "@mui/icons-material/PrintTwoTone";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { LocalizationProvider } from "@mui/x-date-pickers";
import { DatePicker } from "@mui/x-date-pickers";
import { DemoContainer } from "@mui/x-date-pickers/internals/demo";
import Divider from "@mui/material/Divider";
import { Rating } from "@mui/material";
import { addRating } from "../reducers/bookSlice";
import { onChangeRatingHover } from "../reducers/bookSlice";
import { getLabelText } from "../units/rating.ts";
import { labels } from "../units/rating.ts";
import { formatsBook } from "../units/formatsBook.js";
import { genre } from "../units/genre.js";
import { Autocomplete } from "@mui/material";
import StarIcon from "@mui/icons-material/Star";
import { Link } from "react-router-dom";
import { addErrorFolder, addErrorName } from "../reducers/optionslice.js";

function AddBooks() {
  const ratingHover = useSelector((state) => state.books.ratingHover);
  const folders = useSelector((state) => state.libraryfolder.folder);
  const ratingValue = useSelector((state) => state.books.rating);
  const errorName = useSelector((state) => state.options.errorName);
  const errorFolder = useSelector((state) => state.options.errorFolder);
  // const [name, setName] = useState("");
  // const [folder, setFolder] = useState("");
  const [postState, setPostState] = useState(null);
  const theme = useTheme();
  const dispatch = useDispatch();

  const handleSubmit = (e) => {
    e.preventDefault();

    const formData = new FormData(e.target);
    const obj = Object.fromEntries(formData);
    const data = { ...obj, id: Date.now() };
    if (data.name === "") {
      dispatch(addErrorName(true));
      return;
    }

    if (data.folder === "") {
      dispatch(addErrorFolder(true));
      return;
    }

    if (postState) {
      let image1 = URL.createObjectURL(data.poster);
      localStorage.setItem([data.poster.name], image1);
    } else {
      data.poster = "/image/book.png";
    }
    dispatch(addBooks(data));
    dispatch(toggleAddBooksModal());
  };
  const onChangePoster = (e) => {
    console.log(e.target.files[0].name);
    let image = URL.createObjectURL(e.target.files[0]);
    localStorage.setItem([e.target.files[0].name], image);
    setPostState(e.target.files[0].name);
  };

  const handleNameChange = (e) => {
    //setName(e.target.value);
    if (e.target.validity.valid) {
      dispatch(addErrorName(false));
    } else {
      dispatch(addErrorName(true));
    }
  };

  const handleFolderChange = (e) => {
    if (e.target.textContent === "") {
      dispatch(addErrorFolder(true));
    } else {
      dispatch(addErrorFolder(false));
    }
  };

  return (
    <div className="container">
      <AppBar
        sx={{
          p: 2,
          display: "flex",
          alignItems: "center",
          gap: "16px",
          flexDirection: "row",
        }}
      >
        <Link
          to="books"
          onClick={() => dispatch(toggleAddBooksModal())}
          style={{ display: "flex", alignItems: "center" }}
        >
          <KeyboardBackspaceOutlinedIcon
            sx={{ color: theme.palette.primary.light }}
          />
        </Link>
        <Typography sx={{ color: theme.palette.primary.light }} variant="h5">
          Додати книгу
        </Typography>
      </AppBar>
      <form className="form" noValidate onSubmit={handleSubmit}>
        <TextField
          sx={{
            "& .MuiInputLabel-root.Mui-error": {
              color: "#e9bf06",
            },
            "& .MuiOutlinedInput-root.Mui-error .MuiOutlinedInput-notchedOutline":
              {
                border: "3px solid #e9bf06",
              },
            "& .MuiFormHelperText-root.Mui-error": {
              color: "#e9bf06",
            },
          }}
          required
          name="name"
          label="Назва"
          error={errorName}
          onChange={handleNameChange}
          helperText={errorName ? "Поле обов'язкове для заповнення" : ""}
        />

        <Box sx={{ display: "flex", gap: "6px" }}>
          <TextField
            sx={{ width: "70%" }}
            id="series"
            name="series"
            label="Серія"
            variant="outlined"
          />
          <TextField id="part" name="part" label="Частина" variant="outlined" />
        </Box>
        <Box sx={{ display: "flex", gap: "6px", width: "100%" }}>
          <TextField
            sx={{ width: "30%" }}
            id="lastName"
            name="lastName"
            label="Прізвище"
            variant="outlined"
          />
          <TextField
            sx={{ width: "100%" }}
            id="firstName"
            name="firstName"
            label="Ім'я"
            variant="outlined"
          />
        </Box>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            gap: "16px",
          }}
        >
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: "6px",
              width: "30%",
            }}
          >
            <Box sx={{ width: 140 }}>
              <img
                width={"100%"}
                src={
                  postState
                    ? localStorage.getItem([postState])
                    : "/image/book.png"
                }
              />
            </Box>
            <Button variant="outlined">
              <label className="label-file" htmlFor="poster">
                <input
                  id="poster"
                  type="file"
                  name="poster"
                  className="input-file"
                  onChange={onChangePoster}
                />

                <CollectionsIcon />
              </label>
            </Button>
          </Box>
          <Box
            sx={{
              display: "flex",
              flexDirection: "column",
              gap: "6px",
              flexGrow: 1,
            }}
          >
            <Box
              sx={{
                display: "flex",
                alignItems: "center",
                gap: "8px",
              }}
            >
              <PrintTwoToneIcon color="secondary" fontSize="large" />
              <TextField
                id="publish"
                name="publish"
                fullWidth
                label="Видавництво"
                variant="outlined"
              />
            </Box>
            <LocalizationProvider dateAdapter={AdapterDayjs}>
              <DemoContainer components={["DatePicker"]}>
                <DatePicker
                  label="Дата"
                  id="date"
                  name="date"
                  fullWidth
                  slotProps={{
                    textField: {
                      helperText: "MM/DD/YYYY",
                      sx: { width: "100%" },
                    },

                    mobilePaper: {
                      sx: { backgroundColor: theme.palette.background },
                    },
                    desktopPaper: {
                      sx: { backgroundColor: theme.palette.background },
                    },
                  }}
                />
              </DemoContainer>
            </LocalizationProvider>
          </Box>
        </Box>
        <Box
          sx={{
            "& > legend": { m: 2 },
            alignSelf: "center",
            m: 3,
            display: "flex",
            alignItems: "center",
            gap: "12px",
          }}
        >
          <Rating
            size="large"
            name="rating"
            precision={0.5}
            value={ratingValue}
            getLabelText={getLabelText}
            onChange={(event, newValue) => {
              dispatch(addRating(newValue));
            }}
            onChangeActive={(event, newHover) => {
              dispatch(onChangeRatingHover(newHover));
            }}
            emptyIcon={
              <StarIcon style={{ opacity: 0.55 }} fontSize="inherit" />
            }
          />
          {ratingValue !== null && (
            <Box sx={{ ml: 2, color: "#ffb30e" }}>
              {labels[ratingHover !== -1 ? ratingHover : ratingValue]}
            </Box>
          )}
        </Box>
        <Autocomplete
          disablePortal
          options={formatsBook}
          fullWidth
          slotProps={{
            popper: {
              sx: { backgroundColor: theme.palette.background },
            },
          }}
          renderInput={(params) => (
            <TextField {...params} label="Формат" id="format" name="format" />
          )}
        />

        <Box sx={{ display: "flex", gap: "6px", width: "100%" }}>
          <TextField
            sx={{ width: "70%" }}
            id="language"
            name="language"
            label="Мова"
            variant="outlined"
          />
          <TextField
            sx={{ flexGrow: 1 }}
            id="page"
            name="page"
            label="Сторінки"
            variant="outlined"
          />
        </Box>
        <Box
          sx={{
            display: "flex",
            gap: "6px",
            width: "100%",
            alignItems: "center",
          }}
        >
          <TextField
            sx={{ flexGrow: 1 }}
            id="price"
            name="price"
            label="Ціна"
            variant="outlined"
          />
          <Typography>грн</Typography>
        </Box>
        <Autocomplete
          disablePortal
          options={genre}
          fullWidth
          slotProps={{
            popper: {
              sx: { backgroundColor: theme.palette.background },
            },
          }}
          renderInput={(params) => (
            <TextField {...params} label="Жанр" id="genre" name="genre" />
          )}
        />
        <Box display={"flex"} alignItems={"center"}>
          <ListAltIcon color="secondary" fontSize="large" />
          <span>Резюме</span>
        </Box>
        <TextareaAutosize
          aria-label="minimum height"
          minRows={3}
          style={{ backgroundColor: theme.palette.background }}
          name="rezume"
          id="rezume"
          fullWidth
        />
        <Autocomplete
          disablePortal
          options={folders}
          fullWidth
          onChange={handleFolderChange}
          getOptionLabel={(option) => option.name}
          slotProps={{
            popper: {
              sx: { backgroundColor: theme.palette.background },
            },
            root: {
              sx: { backgroundColor: "red" },
            },
          }}
          renderInput={(params) => (
            <TextField
              {...params}
              sx={{
                "& .MuiInputLabel-root.Mui-error": {
                  color: "#e9bf06",
                },
                "& .MuiOutlinedInput-root.Mui-error .MuiOutlinedInput-notchedOutline":
                  {
                    border: "3px solid #e9bf06",
                  },
                "& .MuiFormHelperText-root.Mui-error": {
                  color: "#e9bf06",
                },
              }}
              onChange={handleFolderChange}
              label="Полиці"
              id="folder"
              required
              error={errorFolder}
              helperText={errorFolder ? "Поле обов'язкове для заповнення" : ""}
              name="folder"
            />
          )}
        />
        <Box
          sx={{
            position: "sticky",
            bottom: "0",
            zIndex: "1000",
          }}
        >
          <Stack
            sx={{
              justifyContent: "center",
            }}
            direction="row"
            spacing={2}
            divider={<Divider orientation="vertical" flexItem />}
          >
            <Button
              variant="contained"
              sx={{ color: theme.palette.primary.light }}
              onClick={() => {
                dispatch(toggleAddBooksModal());
              }}
              type="button"
            >
              відмінити
            </Button>
            <Button
              variant="contained"
              sx={{ color: theme.palette.primary.light }}
              type="submit"
            >
              зберегти
            </Button>
          </Stack>
        </Box>
      </form>
    </div>
  );
}

export { AddBooks };
