import { createSlice } from "@reduxjs/toolkit";
import { act } from "react";
import { myListBooks } from "../units/initialStateBooks";
const bookSlice = createSlice({
  name: "books",
  initialState: {
    book: [...myListBooks],
    listInActiveBooks: [],
    searchValue: "",
    modalAddOpen: false,
    detailsOpen: false,
    selectedBook: {},
    stateInActiveBook: false,
    editOpen: false,
    rating: 2.5,
    ratingHover: -1,
  },
  reducers: {
    addBooks: (state, action) => {
      state.book.push(action.payload);
    },
    toggleAddBooksModal: (state) => {
      state.modalAddOpen = !state.modalAddOpen;
    },
    toggleInActiveBook: (state) => {
      state.stateInActiveBook = !state.stateInActiveBook;
    },
    updateNameFolder: (state, action) => {
      // if (state.book.length > 0) {
      // const bookIndex = state.book.findIndex(
      //   (item) => item.folder === action.payload.oldName
      // );
      state.book.map((item) =>
        item.folder === action.payload.oldName
          ? (item.folder = action.payload.newName)
          : item.folder
      );
      // if (bookIndex > -1) {
      //   state.book[bookIndex].folder = action.payload.newName;
      // }
    },
    openDetailsBook: (state, action) => {
      state.selectedBook = action.payload;
      state.detailsOpen = !state.detailsOpen;
    },
    closeDetailsBook: (state) => {
      state.detailsOpen = false;
      state.stateInActiveBook = false;
    },
    toggleEditBook: (state) => {
      state.editOpen = !state.editOpen;
    },
    editBooks: (state, action) => {
      state.book = state.book.filter(
        (item) => item.id !== state.selectedBook.id
      );
      state.book.push({ ...action.payload, id: state.selectedBook.id });
      state.selectedBook = { ...action.payload, id: state.selectedBook.id };
      state.editOpen = false;
      state.detailsOpen = true;
    },
    deleteBook: (state) => {
      state.book = state.book.filter(
        (item) => item.id !== state.selectedBook.id
      );
      state.selectedBook = {};
      state.detailsOpen = !state.detailsOpen;
    },
    onChangeSearchValue: (state, action) => {
      state.searchValue = action.payload;
    },
    addRating: (state, action) => {
      state.rating = action.payload;
    },
    onChangeRatingHover: (state, action) => {
      state.ratingHover = action.payload;
    },
    addInActiveBook: (state) => {
      state.listInActiveBooks.push(state.selectedBook);
      state.book = state.book.filter(
        (item) => item.id !== state.selectedBook.id
      );
      state.detailsOpen = false;
    },
    setBackInActiveBooks: (state) => {
      state.book.push(state.selectedBook);
      state.listInActiveBooks = state.listInActiveBooks.filter(
        (item) => item.id !== state.selectedBook.id
      );
      state.stateInActiveBook = false;
      state.detailsOpen = false;
    },
  },
});
export const {
  toggleAddBooksModal,
  addBooks,
  updateNameFolder,
  toggleEditBook,
  openDetailsBook,
  closeDetailsBook,
  editBooks,
  deleteBook,
  onChangeSearchValue,
  addRating,
  onChangeRatingHover,
  addInActiveBook,
  toggleInActiveBook,
  setBackInActiveBooks,
} = bookSlice.actions;
export { bookSlice };
