import { createSlice } from "@reduxjs/toolkit";
import { SortBooksModal } from "../components/modals/SortBooksModal";
const optionSlice = createSlice({
  name: "options",
  initialState: {
    sortBooksOpen: false,
    sortOptions: {},
    view: true,
    errorName: false,
    errorFolder: false,
    errorNameFolder: "",
  },
  reducers: {
    onchangeView: (state) => {
      state.view = !state.view;
    },
    addErrorName: (state, action) => {
      state.errorName = action.payload;
    },
    addErrorFolder: (state, action) => {
      state.errorFolder = action.payload;
    },
    addErrorNameFolder: (state, action) => {
      state.errorNameFolder = action.payload;
    },
    toggleSortBooksModal: (state, action) => {
      state.sortBooksOpen = action.payload;
    },
    upDateSortOptions: (state, action) => {
      state.sortOptions = action.payload;
    },
  },
});
export const {
  toggleSortBooksModal,
  upDateSortOptions,
  onchangeView,
  addErrorFolder,
  addErrorName,
  addErrorNameFolder,
} = optionSlice.actions;
export { optionSlice };
