import { makeStyles } from "@mui/styles";
import { alpha, useTheme } from "@mui/material";

export const headerStyle = makeStyles((theme) => ({
  hide: {
    display: "none",
  },
  root: {
    flexGrow: 1,
  },
  menuButton: {
    display: "none",
    marginRight: useTheme().spacing(2),
    [useTheme().breakpoints.down("sm")]: { display: "block" },
    justifyContent: "space-between",
  },
  search: {
    position: "relative",
    borderRadius: useTheme().shape.borderRadius,
    backgroundColor: alpha(useTheme().palette.common.white, 0.15),
    "&:hover": {
      backgroundColor: alpha(useTheme().palette.common.white, 0.25),
    },
    marginLeft: 0,
    width: "100%",
    [useTheme().breakpoints.up("sm")]: {
      marginLeft: useTheme().spacing(1),
      width: "auto",
    },
  },
  searchIcon: {
    padding: useTheme().spacing(0, 2),
    height: "100%",
    position: "absolute",
    pointerEvents: "none",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  title: {
    flexGrow: 1,
    display: "none",
    color: useTheme().palette.primary.light,
    [useTheme().breakpoints.up("sm")]: {
      display: "flex",
      gap: "10px",
      alignItems: "center",
    },
  },
  linkActive: {
    borderRadius: useTheme().shape.borderRadius,
    color: "red",
    backgroundColor: alpha(useTheme().palette.common.white, 0.15),
    "&:hover": {
      backgroundColor: alpha(useTheme().palette.common.white, 0.25),
    },
  },
  link: {
    color: useTheme().palette.secondary.dark,
    fontSize: "1.1em",
    padding: "4px 16px",
    borderRadius: "4px",
    "&:hover": {
      backgroundColor: alpha(useTheme().palette.common.white, 0.25),
    },
  },
  inputInput: {
    textAlign: "center",
    padding: useTheme().spacing(2, 2, 2, 2),
    color: useTheme().palette.secondary.dark,
    paddingLeft: `calc(1em + ${useTheme().spacing(4)}px)`,
    transition: useTheme().transitions.create("width"),
    width: "100%",
    [useTheme().breakpoints.up("sm")]: {
      width: "16ch",
      "&:focus": {
        width: "30ch",
      },
    },
  },
  rotateIcon: {
    transform: "rotate(180deg)",
  },
  menuItems: {
    display: "flex",
    width: "50%",

    gap: "16px",
    [useTheme().breakpoints.down("sm")]: {
      display: "none",
    },
  },
}));
