export const filterElements = (elements, filteredValue) =>
  elements.filter(
    (element) =>
      element.name.toLowerCase().includes(filteredValue.toLowerCase()) ||
      element.lastName.toLowerCase().includes(filteredValue.toLowerCase())
  );
export const filtereFolders = (elements, filteredValue) =>
  elements.filter((element) =>
    element.name.toLowerCase().includes(filteredValue.toLowerCase())
  );
